import { siteConfig } from "@/data/site-config";

/**
 * robots.txt — generated by Next.js at build time.
 * Accessible at /robots.txt
 */
export default function robots() {
  return {
    rules: [
      {
        userAgent: "*",
        allow:     "/",
        disallow:  ["/_next/", "/api/"],
      },
    ],
    sitemap:  `${siteConfig.url}/sitemap.xml`,
    host:     siteConfig.url,
  };
}
